package net.minecraft.nbt;
import java.util.*;public class CompoundTag extends Tag {private final Map<String,Object> values=new HashMap<>();public void put(String k,Tag v){values.put(k,v);}public void putInt(String k,int v){values.put(k,v);}public int getInt(String k){return values.get(k) instanceof Integer v?v:0;}public void putBoolean(String k,boolean v){values.put(k,v);}public boolean getBoolean(String k){return Boolean.TRUE.equals(values.get(k));}public CompoundTag getCompound(String k){return values.get(k) instanceof CompoundTag v?v:new CompoundTag();}public ListTag getList(String k,int type){return values.get(k) instanceof ListTag v?v:new ListTag();}public boolean contains(String k){return values.containsKey(k);}public Set<String> getAllKeys(){return values.keySet();}}
